import sys

def max_volatility(n, m, k):
    """返回在给定 n, m, k 下波动值的最大可能值，若不存在合法序列则返回 -1"""
    if n == 1:
        # 没有相邻元素
        return 0

    if k == 0:
        # 所有元素必须相等
        if m % n == 0:
            return 0
        return -1

    # 此时 n >= 2 且 k >= 1
    if n == 2:
        return m

    # n >= 3
    if k == 1:
        return m
    else:               # k >= 2
        return 2 * m

def solve():
    data = sys.stdin.buffer.read().split()
    t = int(data[0])
    idx = 1
    out_lines = []

    for _ in range(t):
        n = int(data[idx]); m = int(data[idx + 1]); q = int(data[idx + 2])
        idx += 3

        for _ in range(q):
            k = int(data[idx]); g = int(data[idx + 1])
            idx += 2

            max_v = max_volatility(n, m, k)

            if max_v != -1 and max_v >= g:
                out_lines.append("YES")
            else:
                out_lines.append("NO")

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
```

